import { Flex, Tag, Text } from "@chakra-ui/react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import { ErrorAlert } from "../../try-assistant/ConversationLog/Event/ErrorAlert";
import { deriveLlmCallView, type LlmCallMessage } from "../../try-assistant/deriveLlmCallView";
import type { ConversationEvent } from "../../types";
import { DetailView, InfoField } from "./blocks";

interface LlmCallEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

function messagesAsText(messages: LlmCallMessage[]): string {
  return messages.map((message) => `[${message.role}]\n${message.content}`).join("\n\n");
}

/** Detail panel for one LLM completion from the engine's call log. */
export const LlmCallEventInfo = ({ event, onClose }: LlmCallEventInfoProps) => {
  const record = event.metadata?.llm_call;
  if (!record) return null;
  const view = deriveLlmCallView(record);

  return (
    <DetailView title="LLM call" onClose={onClose}>
      <InfoField label="Model">
        <Text textStyle="sm">{view.model}</Text>
      </InfoField>

      {view.purpose && (
        <InfoField label="Purpose">
          <Text textStyle="sm" data-testid="llm-call-purpose">
            {view.purpose}
          </Text>
        </InfoField>
      )}

      {(view.durationLabel || view.tokensLabel) && (
        <InfoField label="Usage">
          <Text textStyle="sm" data-testid="llm-call-usage">
            {[view.durationLabel, view.tokensLabel].filter(Boolean).join(" · ")}
          </Text>
        </InfoField>
      )}

      {view.toolNames.length + view.gatedToolNames.length > 0 && (
        <InfoField label="Tools">
          <Flex gap="1.5" flexWrap="wrap" data-testid="llm-call-tools">
            {view.toolNames.map((toolName) => (
              <Tag.Root
                key={toolName}
                size="sm"
                variant="surface"
                colorPalette={view.responseToolNames.includes(toolName) ? "purple" : "gray"}
              >
                <Tag.Label>{toolName}</Tag.Label>
              </Tag.Root>
            ))}
            {view.gatedToolNames.map((toolName) => (
              <Tag.Root
                key={toolName}
                size="sm"
                variant="outline"
                colorPalette="gray"
                opacity="deactivated"
                data-testid="llm-call-gated-tool"
              >
                <Tag.Label>{toolName}</Tag.Label>
              </Tag.Root>
            ))}
          </Flex>
        </InfoField>
      )}

      {view.isError && (
        <ErrorAlert title="This LLM call failed:" message={view.errorMessage ?? undefined} />
      )}

      {view.promptMessages.length > 0 && (
        <InfoField label="Prompt">
          <RasaCodeBlock
            code={messagesAsText(view.promptMessages)}
            data-testid="llm-call-prompt"
            maxCodeHeight="96"
          />
        </InfoField>
      )}

      {view.responseMessages.length > 0 && (
        <InfoField label="Response">
          <RasaCodeBlock
            code={messagesAsText(view.responseMessages)}
            data-testid="llm-call-response"
            maxCodeHeight="80"
          />
        </InfoField>
      )}
    </DetailView>
  );
};
